INSERT INTO `${ticketTable}` (
    `${itemFk}`, username, status, apply_at, remark
    , fine_yuan
    , remind_msg
    , approve_at
    , attach_url
    , qty
    , due_at
    , period_start, period_end
) VALUES (
    #{itemId}, #{username}, #{status}, NOW(), #{remark}
    , 0
    , ''
    , NOW()
    , #{attachUrl}
    , #{qty}
    , #{dueAt}
    , #{periodStart}, #{periodEnd}
)

INSERT INTO `${ticketTable}` (
    username, title, location, type_id, room_id, status, apply_at, remark
    , attach_url
    , priority
    , contact_phone
) VALUES (
    #{username}, #{title}, #{location}, #{typeId}, #{roomId}, 'pending', NOW(), #{remark}
    , #{attachUrl}
    , #{priority}
    , #{contactPhone}
)

