SELECT COUNT(*) FROM `${ticketTable}` WHERE username=#{username}
AND status IN ('pending','pending_final')
AND status IN ('pending','pending_final','approved','overdue')

SELECT COUNT(*) FROM `${ticketTable}` t
JOIN `${itemTable}` i ON t.`${itemFk}`=i.id
WHERE t.username=#{username}
  AND t.status IN ('pending','pending_final','approved','overdue')
  AND i.category_id=#{categoryId}

mapper.update:
UPDATE `${ticketTable}` SET pickup_at=NOW()
, pickup_place=#{pickupPlace}
, actual_qty=#{actualQty}
WHERE id=#{id}

UPDATE `${ticketTable}` SET status='rejected', approve_at=NOW(), remark=#{remark}
, assignee_username=#{assigneeUsername}
WHERE id=#{id}

UPDATE `${ticketTable}` SET status='pending_final', remark=#{remark}
, assignee_username=#{assigneeUsername}
WHERE id=#{id}

UPDATE `${ticketTable}` SET status='approved',

    approve_at=#{approveAt}
    approve_at=NOW()

, remark=#{remark}
, assignee_username=#{assigneeUsername}
, due_at=#{dueAt}
, fine_yuan=0
, remind_msg=''
WHERE id=#{id}

mapper.select:
SELECT id FROM `${ticketTable}`
WHERE `${itemFk}`=#{itemId} AND id<>#{excludeId}
  AND status IN ('pending','pending_final')

mapper.update:
UPDATE `${ticketTable}` SET status='returned', return_at=NOW()
, remind_msg=#{remindMsg}
WHERE id=#{id}

UPDATE `${ticketTable}`
SET status=#{status}, fine_yuan=#{fineYuan}, remind_msg=#{remindMsg}, reminded_at=#{remindedAt}
WHERE id=#{id}

